const OKLCH_REGEX = /^oklch\(\s*([+-]?\d*\.?\d+)(%)?\s+([+-]?\d*\.?\d+)\s+([+-]?\d*\.?\d+)(?:deg)?\s*\)$/i

interface ParsedOklch {
  l: number
  c: number
  h: number
}

const clamp = (value: number, min = 0, max = 1) => Math.min(Math.max(value, min), max)

const toRadians = (degrees: number) => (degrees * Math.PI) / 180

const linearChannelToSrgb = (value: number) => {
  const clamped = clamp(value)
  return clamped <= 0.0031308 ? clamped * 12.92 : 1.055 * Math.pow(clamped, 1 / 2.4) - 0.055
}

const srgbChannelToHex = (value: number) => {
  const clamped = clamp(value)
  return Math.round(clamped * 255)
    .toString(16)
    .padStart(2, '0')
}

const parseOklch = (color: string): ParsedOklch | null => {
  const match = color.trim().match(OKLCH_REGEX)
  if (!match) return null

  const [, lRaw, lPercentFlag, cRaw, hRaw] = match
  const l = Number.parseFloat(lRaw ?? '')
  const c = Number.parseFloat(cRaw ?? '')
  const h = Number.parseFloat(hRaw ?? '')

  if ([l, c, h].some(Number.isNaN)) {
    return null
  }

  return {
    l: lPercentFlag ? l / 100 : l,
    c,
    h,
  }
}

const oklchToLinearSrgb = ({l, c, h}: ParsedOklch) => {
  const a = Math.cos(toRadians(h)) * c
  const b = Math.sin(toRadians(h)) * c

  const l_ = l + 0.3963377774 * a + 0.2158037573 * b
  const m_ = l - 0.1055613458 * a - 0.0638541728 * b
  const s_ = l - 0.0894841775 * a - 1.291485548 * b

  const l3 = l_ ** 3
  const m3 = m_ ** 3
  const s3 = s_ ** 3

  return {
    r: 4.0767416621 * l3 - 3.3077115913 * m3 + 0.2309699292 * s3,
    g: -1.2684380046 * l3 + 2.6097574011 * m3 - 0.3413193965 * s3,
    b: -0.0041960863 * l3 - 0.7034186147 * m3 + 1.707614701 * s3,
  }
}

const oklchToHex = (color: ParsedOklch): string => {
  const {r, g, b} = oklchToLinearSrgb(color)

  const sr = linearChannelToSrgb(r)
  const sg = linearChannelToSrgb(g)
  const sb = linearChannelToSrgb(b)

  return `#${srgbChannelToHex(sr)}${srgbChannelToHex(sg)}${srgbChannelToHex(sb)}`
}

/**
 * Convert supported CSS color strings to hexadecimal for assistive tech announcements.
 * Currently supports OKLCH values as used in Tailwind's palette and returns normalized hex strings.
 */
export const colorValueToHex = (color: string | null): string | null => {
  if (!color) return null

  const trimmed = color.trim()

  if (trimmed.startsWith('#')) {
    if (trimmed.length === 4) {
      const short = trimmed.slice(1)
      const expanded = short
        .split('')
        .map(char => `${char}${char}`)
        .join('')
      return `#${expanded}`.toLowerCase()
    }

    return trimmed.toLowerCase()
  }

  if (trimmed.toLowerCase().startsWith('oklch')) {
    const parsed = parseOklch(trimmed)
    if (!parsed) return null

    try {
      return oklchToHex(parsed).toLowerCase()
    } catch {
      return null
    }
  }

  return null
}

const INTERMEDIATE_SCALE_VALUES = ['200', '300', '400', '500', '600', '700', '800', '900'] as const

const toCapitalizedColorName = (value: string) => {
  if (!value) return value
  return value.replace(/(^|\s|-)([a-z])/g, (_, prefix, char) => `${prefix}${char.toUpperCase()}`)
}

const normalizeScaleLabel = (step: string) => {
  if (step === '50') return 'Lightest'
  if (step === '950') return 'Darkest'
  if ((INTERMEDIATE_SCALE_VALUES as readonly string[]).includes(step)) return step
  return step
}

/**
 * Build an accessible label for a color swatch option that follows the design system naming scheme.
 */
export const buildColorSwatchLabel = (colorName: string, step: string) => {
  const normalized = normalizeScaleLabel(step)
  if (normalized === 'Lightest') {
    return `Lightest ${colorName.toLowerCase()}`
  }
  if (normalized === 'Darkest') {
    return `Darkest ${colorName.toLowerCase()}`
  }

  return `${toCapitalizedColorName(colorName)} ${normalized}`.trim()
}
